style.css:
@-moz-document domain("roblox.com") {
/* Фон всей страницы */
  body {
    background: url("https://i.postimg.cc/Jz8wK04H/6503159171b9665e4f850f3570f2f926.jpg") no-repeat center center fixed !important;
    background-size: cover !important;
    color: #d2e8fe !important;
  }

  /* Полупрозрачные панели */
  .navbar,
  .menu-bar,
  .container,
  .header,
  .footer,
  .section,
  .rbx-body,
  .rbx-navbar,
  .rbx-header,
  .rbx-footer,
  .game-card,
  .profile-header,
  .avatar-card-container {
    background-color: rgba(0, 51, 102, 0.85) !important;
    border: none !important;
  }

  /* Текст */
  body, 
  .text, 
  .rbx-text, 
  .game-name, 
  .section-content, 
  .header-title,
  .profile-name,
  .item-card-name {
    color: #d2e8fe !important;
  }

  /* Ссылки */
  a {
    color: #d2e8fe !important;
  }

  a:hover {
    color: #ffffff !important;
    text-decoration: underline !important;
  }

  /* Кнопки */
  button, 
  .btn-primary,
  .btn-secondary {
    background-color: rgba(0, 51, 102, 0.9) !important;
    color: #d2e8fe !important;
    border: 1px solid #d2e8fe !important;
  }

  button:hover, 
  .btn-primary:hover,
  .btn-secondary:hover {
    background-color: rgba(0, 85, 153, 0.95) !important;
    color: #ffffff !important;
  }
}
